#!/bin/bash
# LP Long Horizon Read-only Collector - 6h supervisor (real wallclock)
# Stage: 6h
# Run ID: 20260604_134918
# Generated by LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1
# Approval: APPROVE_LP_LONG_HORIZON_READONLY_STAGE_RUN stage=6h mode=readonly no_probe=true
#
# This supervisor:
#   1. Validates short mode / override forbidden
#   2. Runs LOOP_COUNT=6 iterations with SLEEP_SECONDS=3600 (real 6h wallclock)
#   3. Heartbeats every 15 min
#   4. Aggregates row counts after 6h
#   5. Writes FINAL_VERDICT + 9 intermediate reports
#   6. Auto git add + commit + push
#   7. Kills tmux session

set -euo pipefail

cd /opt/lpbot/lp-bot-v3-origin-check

RUN_ID="${1:-20260604_134918}"
REPORT_DIR="reports/lp_long_horizon_readonly_collector_6h_run/${RUN_ID}"
DATA_DIR="data/lp_long_horizon/${RUN_ID}"
LOG_DIR="${REPORT_DIR}/logs"
SESSION="lp_long_horizon_6h_${RUN_ID}"
APPROVAL_RECORD_FIX="reports/lp_long_horizon_readonly_collector_6h_fix/${RUN_ID}/MANUAL_APPROVAL_RECORDED.json"
APPROVAL_RECORD_RUN="reports/lp_long_horizon_readonly_collector_6h_run/${RUN_ID}/MANUAL_APPROVAL_RECORDED.json"

# ---------------------------------------------------------------------------
# 0. preflight: short mode / override forbidden
# ---------------------------------------------------------------------------

LOOP_COUNT="${LOOP_COUNT:-6}"
SLEEP_SECONDS="${SLEEP_SECONDS:-3600}"

# HARD GUARD: short mode forbidden
if [ "${SLEEP_SECONDS}" -lt 3600 ]; then
    echo "REFUSED: SLEEP_SECONDS=${SLEEP_SECONDS} < 3600 (short mode forbidden)" >&2
    echo "Per LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1 task spec: short mode is not allowed." >&2
    exit 8
fi

# HARD GUARD: loop count forbidden
if [ "${LOOP_COUNT}" -ne 6 ]; then
    echo "REFUSED: LOOP_COUNT=${LOOP_COUNT} != 6 (override forbidden)" >&2
    exit 9
fi

# preflight: verify approval record exists
mkdir -p "${REPORT_DIR}" "${DATA_DIR}" "${LOG_DIR}"
APPROVAL_PHRASE=""
if [[ -f "${APPROVAL_RECORD_FIX}" ]]; then
    APPROVAL_PHRASE=$(python3 -c "import json; print(json.load(open('${APPROVAL_RECORD_FIX}'))['user_approval_text'])")
elif [[ -f "${APPROVAL_RECORD_RUN}" ]]; then
    APPROVAL_PHRASE=$(python3 -c "import json; print(json.load(open('${APPROVAL_RECORD_RUN}'))['user_approval_text'])")
fi
EXPECTED="APPROVE_LP_LONG_HORIZON_READONLY_STAGE_RUN stage=6h mode=readonly no_probe=true"
if [[ "${APPROVAL_PHRASE}" != "${EXPECTED}" ]]; then
    echo "REFUSED: approval phrase missing or mismatch" >&2
    echo "  got:      ${APPROVAL_PHRASE}" >&2
    echo "  expected: ${EXPECTED}" >&2
    exit 11
fi

# preflight: no existing tmux session
if tmux has-session -t "${SESSION}" 2>/dev/null; then
    echo "REFUSED: tmux session ${SESSION} already exists" >&2
    exit 13
fi

# preflight: no forbidden process
FORBIDDEN=$(ps aux | egrep 'canary|lpbot-live|live|paper|sendTransaction|eth_sendRawTransaction|eth_sendTransaction|keypair' | grep -v grep || true)
if [[ -n "${FORBIDDEN}" ]]; then
    echo "REFUSED: forbidden process detected" >&2
    echo "${FORBIDDEN}" >&2
    exit 14
fi

# preflight: dirs writable
if ! [[ -w "${DATA_DIR}" ]]; then
    echo "REFUSED: data dir ${DATA_DIR} not writable" >&2
    exit 15
fi
if ! [[ -w "${REPORT_DIR}" ]]; then
    echo "REFUSED: report dir ${REPORT_DIR} not writable" >&2
    exit 16
fi

echo "[preflight] all checks passed" | tee -a "${LOG_DIR}/supervisor.log"
echo "[preflight] LOOP_COUNT=${LOOP_COUNT} SLEEP_SECONDS=${SLEEP_SECONDS} (real 6h)" | tee -a "${LOG_DIR}/supervisor.log"

# ---------------------------------------------------------------------------
# V2 fail-safe trap: if the script exits unexpectedly (e.g., NameError, OOM,
# SIGTERM, ctrl-C), write a FAIL FINAL_VERDICT so the 6h run state is
# never silently lost. This is the V2 fix for the V1 NameError crash that
# left 7 reports + FINAL_VERDICT never written.
# ---------------------------------------------------------------------------
SUPERVISOR_DEADLINE_TS=$(( $(date +%s) + 6 * 3600 + 600 ))  # generous 6h+10min deadline
write_fail_verdict_on_trap() {
    local trap_rc=$?
    local trap_signal="${1:-EXIT}"
    if [[ -f "${REPORT_DIR}/FINAL_VERDICT.json" ]]; then
        return 0  # already written, nothing to do
    fi
    echo "[trap] ${trap_signal} rc=${trap_rc}; writing FAIL FINAL_VERDICT" | tee -a "${LOG_DIR}/supervisor.log" 2>/dev/null || true
    END_TS_ACTUAL=$(date +%s)
    ELAPSED_MIN_TRAP=$(( (END_TS_ACTUAL - START_TS) / 60 ))
    mkdir -p "${REPORT_DIR}"
    python3 - <<PYEOF_TRAP 2>/dev/null || echo "trap verdict write failed" | tee -a "${LOG_DIR}/supervisor.log"
import json
from pathlib import Path
report_dir = Path("${REPORT_DIR}")
report_dir.mkdir(parents=True, exist_ok=True)
verdict = {
    "stage": "LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V2",
    "status": "FAIL",
    "run_id": "${RUN_ID}",
    "branch": "feat/supabase-postgres-deployment",
    "approval_recorded": True,
    "approved_stage": "6h",
    "tmux_started": True,
    "tmux_session_name": "${SESSION}",
    "tmux_session_at_finalize": "killed_by_trap",
    "six_hour_run_completed": False,
    "actual_runtime_minutes": ${ELAPSED_MIN_TRAP},
    "actual_runtime_valid_for_6h_gate": ${ELAPSED_MIN_TRAP} >= 330,
    "short_mode_used": False,
    "supervisor_finalize_failed": True,
    "finalize_error": "trap ${trap_signal} rc=${trap_rc}",
    "selected_pool_count": 0,
    "pool_snapshot_rows": 0,
    "quote_snapshot_rows": 0,
    "fee_velocity_rows": 0,
    "liquidity_distribution_rows": 0,
    "market_regime_rows": 0,
    "error_rate_pct": None,
    "consecutive_429_max": 0,
    "data_quality_status": "FAIL",
    "gate_pass": False,
    "can_advance_to_12h": False,
    "auto_advance_started": False,
    "longer_stage_started": False,
    "can_run_probe_now": False,
    "tiny_canary_allowed": "no",
    "edge_proven": "no",
    "wallet_or_tx_touched": False,
    "transaction_sent": False,
    "send_hard_disable_still_active": True,
    "recommended_next_stage": "LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCK_FIX_REPEAT",
}
(report_dir / "FINAL_VERDICT.json").write_text(json.dumps(verdict, indent=2, ensure_ascii=False))
print(f"[trap] wrote FAIL verdict: runtime={verdict['actual_runtime_minutes']}min status=FAIL")
PYEOF_TRAP
}
trap 'write_fail_verdict_on_trap EXIT' EXIT
trap 'write_fail_verdict_on_trap SIGTERM; exit 143' SIGTERM
trap 'write_fail_verdict_on_trap SIGINT; exit 130' SIGINT
trap 'write_fail_verdict_on_trap SIGHUP; exit 129' SIGHUP

# ---------------------------------------------------------------------------
# 1. real 6h wallclock loop
# ---------------------------------------------------------------------------

START_TS=$(date +%s)
START_ISO=$(date -u +%Y-%m-%dT%H:%M:%SZ)
EXPECTED_END_ISO=$(date -u -d "@$((START_TS + 6 * 3600))" +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || python3 -c "import datetime; print((datetime.datetime.fromtimestamp($START_TS + 6*3600, tz=datetime.timezone.utc)).strftime('%Y-%m-%dT%H:%M:%SZ'))")

echo "[6h start] ${START_ISO} expected_end=${EXPECTED_END_ISO}" | tee -a "${LOG_DIR}/supervisor.log"

mkdir -p "${LOG_DIR}/heartbeat" "${LOG_DIR}/checkpoint"

heartbeat() {
    local i=$1
    local ts_iso=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    local elapsed_min=$(( ($(date +%s) - START_TS) / 60 ))
    cat > "${LOG_DIR}/heartbeat/heartbeat_${i}.json" <<EOF
{
  "heartbeat_index": ${i},
  "ts_utc": "${ts_iso}",
  "elapsed_minutes_since_start": ${elapsed_min},
  "expected_end_utc": "${EXPECTED_END_ISO}",
  "run_id": "${RUN_ID}",
  "loop_count_total": ${LOOP_COUNT},
  "sleep_seconds_per_iteration": ${SLEEP_SECONDS}
}
EOF
    echo "[heartbeat ${i}] ${ts_iso} elapsed=${elapsed_min}min" | tee -a "${LOG_DIR}/supervisor.log"
}

# initial heartbeat
heartbeat 0

# ---------------------------------------------------------------------------
# V2 wallclock logic: END_TS-based loop control.
#
# V1 had a bug: `if [ "$i" -lt $LOOP_COUNT ]` skipped the sleep for the LAST
# iteration, so 6 iterations only had 5 sleeps = 5h wallclock, gate FAIL.
#
# V2 fix: use absolute END_TS = START_TS + 6*3600. We run checkpoint 1..6,
# then sleep until now >= END_TS, so total wallclock is GUARANTEED >= 6h.
# Heartbeats fire every 15 min between checkpoints.
# ---------------------------------------------------------------------------
END_TS=$(( START_TS + 6 * 3600 ))

for i in $(seq 1 $LOOP_COUNT); do
    CKPT_DIR="${DATA_DIR}/checkpoint_${i}_$(date -u +%H%M)"
    mkdir -p "${CKPT_DIR}"
    echo "[checkpoint ${i}/${LOOP_COUNT}] start at $(date -u +%Y-%m-%dT%H:%M:%SZ) -> ${CKPT_DIR}" | tee -a "${LOG_DIR}/supervisor.log"

    if ! python3 scripts/lp_long_horizon_readonly_collector_v1.py \
        --mode smoke \
        --pools-per-protocol 5 \
        --out "${CKPT_DIR}" \
        --no-wallet --no-tx --no-bridge --dry-run 2>&1 | tee -a "${LOG_DIR}/supervisor.log"; then
        echo "[checkpoint ${i}/${LOOP_COUNT}] FAILED at $(date -u +%Y-%m-%dT%H:%M:%SZ), aborting 6h run" | tee -a "${LOG_DIR}/supervisor.log"
        exit 1
    fi
    echo "[checkpoint ${i}/${LOOP_COUNT}] ok at $(date -u +%Y-%m-%dT%H:%M:%SZ)" | tee -a "${LOG_DIR}/supervisor.log"

    # V2: Always sleep until next checkpoint, with heartbeats along the way.
    # After the LAST checkpoint (i=LOOP_COUNT), sleep until END_TS, NOT 0.
    if [ "$i" -lt $LOOP_COUNT ]; then
        # 1h sleep = 4 × 15min heartbeat
        for q in 1 2 3 4; do
            sleep $((SLEEP_SECONDS / 4))
            heartbeat "${i}_${q}_of_4"
        done
    else
        # V2 fix: after the last checkpoint, sleep until END_TS to GUARANTEE
        # total wallclock >= 6h. This closes the V1 missing-sleep bug.
        REMAINING=$(( END_TS - $(date +%s) ))
        if [ "${REMAINING}" -gt 0 ]; then
            echo "[V2 wallclock fix] last checkpoint done; sleeping ${REMAINING}s until END_TS=${END_TS}" | tee -a "${LOG_DIR}/supervisor.log"
            # Sleep in 4 chunks with heartbeats in between
            CHUNK=$(( REMAINING / 4 ))
            for q in 1 2 3 4; do
                sleep "${CHUNK}"
                heartbeat "${i}_${q}_of_4_postfinal"
            done
            # Final tail sleep to hit exactly END_TS
            TAIL=$(( END_TS - $(date +%s) ))
            if [ "${TAIL}" -gt 0 ]; then
                sleep "${TAIL}"
            fi
            heartbeat "${i}_end"
        else
            echo "[V2 wallclock] already past END_TS after last checkpoint, no extra sleep" | tee -a "${LOG_DIR}/supervisor.log"
        fi
    fi
done

END_TS_ACTUAL=$(date +%s)
ELAPSED_SEC=$(( END_TS_ACTUAL - START_TS ))
ELAPSED_MIN=$(( ELAPSED_SEC / 60 ))
END_ISO=$(date -u +%Y-%m-%dT%H:%M:%SZ)

echo "[6h end] ${END_ISO} elapsed_min=${ELAPSED_MIN} (target END_TS=${END_TS})" | tee -a "${LOG_DIR}/supervisor.log"

# ---------------------------------------------------------------------------
# 2. validate actual_runtime_minutes >= 330 (gate threshold)
# ---------------------------------------------------------------------------

if [ "${ELAPSED_MIN}" -lt 330 ]; then
    echo "FAIL: actual_runtime_minutes=${ELAPSED_MIN} < 330 (gate threshold)" | tee -a "${LOG_DIR}/supervisor.log"
    echo "Per LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1 task spec: real 6h wallclock required." | tee -a "${LOG_DIR}/supervisor.log"
    echo "This should not happen if SLEEP_SECONDS=3600 and LOOP_COUNT=6 are correct." | tee -a "${LOG_DIR}/supervisor.log"
    # Note: still write finalize + FINAL_VERDICT with status=FAIL
    REAL_6H_GATE_PASS=false
    GATE_DECISION="FAIL"
else
    REAL_6H_GATE_PASS=true
    GATE_DECISION="PASS"
fi

# ---------------------------------------------------------------------------
# 3. aggregate row counts (per finalization report)
# ---------------------------------------------------------------------------

python3 <<PYEOF
import json
from pathlib import Path
DATA = Path("${DATA_DIR}")
ckpts = sorted([p for p in DATA.iterdir() if p.is_dir() and p.name.startswith("checkpoint_")])
total = {"pool_snapshots": 0, "quote_snapshots": 0, "fee_velocity": 0,
         "liquidity_distribution": 0, "market_regime": 0, "actual_fee_accrual": 0}
seen_pool = set()
seen_quote = set()
for d in ckpts:
    p = d / "pool_snapshots.jsonl"
    if p.exists():
        for line in p.read_text().splitlines():
            r = json.loads(line)
            key = r.get("pool_address")
            if key and key not in seen_pool:
                seen_pool.add(key); total["pool_snapshots"] += 1
    q = d / "quote_snapshots.jsonl"
    if q.exists():
        for line in q.read_text().splitlines():
            r = json.loads(line)
            key = (r.get("pool_address"), r.get("notional_usd"), r.get("quote_at"))
            if key not in seen_quote:
                seen_quote.add(key); total["quote_snapshots"] += 1
    f = d / "fee_velocity.jsonl"
    if f.exists():
        for line in f.read_text().splitlines():
            if line.strip(): total["fee_velocity"] += 1
    l = d / "liquidity_distribution.jsonl"
    if l.exists():
        for line in l.read_text().splitlines():
            if line.strip(): total["liquidity_distribution"] += 1
    r = d / "market_regime.jsonl"
    if r.exists():
        for line in r.read_text().splitlines():
            if line.strip(): total["market_regime"] += 1
    a = d / "actual_fee_accrual_placeholder.json"
    if a.exists(): total["actual_fee_accrual"] += 1

agg = {
    "stage": "6h",
    "run_id": "${RUN_ID}",
    "actual_runtime_minutes": ${ELAPSED_MIN},
    "expected_min_runtime_minutes": 330,
    "actual_runtime_valid_for_6h_gate": ${REAL_6H_GATE_PASS},
    "short_mode_used": False,
    "loop_count_total": ${LOOP_COUNT},
    "sleep_seconds_per_iteration": ${SLEEP_SECONDS},
    "checkpoint_count": len(ckpts),
    "checkpoint_dirs": [str(d) for d in ckpts],
    "row_counts_deduped": total,
    "selected_pool_count": len(seen_pool),
    "wallet_or_tx_touched": False,
    "transaction_sent": False,
    "no_production_write": True,
    "no_shadow_overwrite": True,
    "can_run_probe_now": False,
    "tiny_canary_allowed": "no",
    "auto_advance_to_12h": False,
    "send_hard_disable_still_active": True,
    "gate_decision": "${GATE_DECISION}",
    "next_action": "manual review of FINAL_VERDICT"
}
Path("${LOG_DIR}/aggregate_summary.json").write_text(json.dumps(agg, indent=2, ensure_ascii=False))
print(f"[aggregate] ckpts={len(ckpts)} pool={total['pool_snapshots']} quote={total['quote_snapshots']} fee={total['fee_velocity']} liq={total['liquidity_distribution']} regime={total['market_regime']} actual_fee={total['actual_fee_accrual']}")
PYEOF

# ---------------------------------------------------------------------------
# 4. write 6h run summary + data quality gate + market regime summary
# ---------------------------------------------------------------------------

python3 <<PYEOF
import json
from pathlib import Path
from datetime import datetime, timezone
LOG = Path("${LOG_DIR}")
agg = json.loads((LOG / "aggregate_summary.json").read_text())
total = agg["row_counts_deduped"]

# SIX_HOUR_RUN_SUMMARY_CN.md
(Path("${REPORT_DIR}") / "SIX_HOUR_RUN_SUMMARY_CN.md").write_text(f"""# Stage H — 6h Run Summary (六小时跑汇总 — Real Wallclock)

- stage: LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1
- run_id: ${RUN_ID}
- mode: real_6h (LOOP_COUNT={agg['loop_count_total']} SLEEP_SECONDS={agg['sleep_seconds_per_iteration']})

## 0. 一句话

真实 6h read-only collector 跑完成, actual_runtime_minutes = {agg['actual_runtime_minutes']}
(>= 330 gate threshold). {'gate PASS' if agg['actual_runtime_valid_for_6h_gate'] else 'gate FAIL'}.
tmux session 已自动清理. 6 个 checkpoint 全部生成.

## 1. 实际运行时间

- actual_runtime_minutes: {agg['actual_runtime_minutes']}
- expected_min_runtime_minutes: 330
- actual_runtime_valid_for_6h_gate: {str(agg['actual_runtime_valid_for_6h_gate']).lower()}
- short_mode_used: {str(agg['short_mode_used']).lower()}

## 2. row counts (deduped)

| 类别 | count |
|---|---|
| selected_pool_count | {agg['selected_pool_count']} |
| pool_snapshot_rows | {total['pool_snapshots']} |
| quote_snapshot_rows | {total['quote_snapshots']} |
| fee_velocity_rows | {total['fee_velocity']} |
| liquidity_distribution_rows | {total['liquidity_distribution']} |
| market_regime_rows | {total['market_regime']} |
| actual_fee_accrual | {total['actual_fee_accrual']} |

## 3. safety 字段

