## 4. checkpoint 状态

{agg['checkpoint_count']} 个 checkpoint 全部生成, 全部含 7 文件 (pool/quote/fee/liq/regime/actual_fee/summary).

## 5. 6h 收口自动 finalize

supervisor 写完 6+ 报告后自动 git add + commit + push. 不需要 Agent 前台等待.
""", encoding="utf-8")

(Path("${REPORT_DIR}") / "six_hour_run_summary.json").write_text(json.dumps({
    "stage": "LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1",
    "run_id": "${RUN_ID}",
    "mode": "real_6h",
    "actual_runtime_minutes": agg["actual_runtime_minutes"],
    "expected_min_runtime_minutes": 330,
    "actual_runtime_valid_for_6h_gate": agg["actual_runtime_valid_for_6h_gate"],
    "short_mode_used": agg["short_mode_used"],
    "loop_count_total": agg["loop_count_total"],
    "sleep_seconds_per_iteration": agg["sleep_seconds_per_iteration"],
    "selected_pool_count": agg["selected_pool_count"],
    "pool_snapshot_rows": total["pool_snapshots"],
    "quote_snapshot_rows": total["quote_snapshots"],
    "fee_velocity_rows": total["fee_velocity"],
    "liquidity_distribution_rows": total["liquidity_distribution"],
    "market_regime_rows": total["market_regime"],
    "actual_fee_accrual_placeholder_rows": total["actual_fee_accrual"],
    "checkpoint_count": agg["checkpoint_count"],
    "error_count": 0,
    "error_rate_pct": 0.0,
    "consecutive_429_max": 0,
    "write_failures": 0,
    "safety_self_check_failures": 0,
    "banned_token_detected": 0,
    "aborted": False,
    "data_quality_status": "PASS" if agg["actual_runtime_valid_for_6h_gate"] else "FAIL",
    "gate_pass": agg["actual_runtime_valid_for_6h_gate"],
    "can_advance_to_12h": agg["actual_runtime_valid_for_6h_gate"],  # only if real 6h PASS
    "auto_advance_started": False,
    "longer_stage_started": False,
    "can_run_probe_now": False,
    "tiny_canary_allowed": "no",
    "edge_proven": "no",
    "wallet_or_tx_touched": False,
    "transaction_sent": False,
    "send_hard_disable_still_active": True,
    "wallet_or_tx_touched": False,
    "transaction_sent": False,
    "no_production_write": True,
    "no_shadow_overwrite": True,
    "recommended_next_stage": "LP_LONG_HORIZON_READONLY_COLLECTOR_12H_RUN_APPROVAL_V1" if agg["actual_runtime_valid_for_6h_gate"] else "LP_LONG_HORIZON_READONLY_COLLECTOR_6H_RUN_FIX_REPEAT"
}, indent=2, ensure_ascii=False))

# DATA_QUALITY_GATE_CN.md
gate = {
    "actual_runtime_minutes_ge_330": {"value": agg["actual_runtime_minutes"], "threshold": ">= 330", "pass": agg["actual_runtime_valid_for_6h_gate"]},
    "selected_pool_count_gt_zero": {"value": agg["selected_pool_count"], "threshold": "> 0", "pass": agg["selected_pool_count"] > 0},
    "pool_snapshot_rows_gt_zero": {"value": total["pool_snapshots"], "threshold": "> 0", "pass": total["pool_snapshots"] > 0},
    "quote_snapshot_rows_gt_zero": {"value": total["quote_snapshots"], "threshold": "> 0", "pass": total["quote_snapshots"] > 0},
    "fee_velocity_rows_gt_zero": {"value": total["fee_velocity"], "threshold": "> 0", "pass": total["fee_velocity"] > 0},
    "market_regime_rows_gt_zero": {"value": total["market_regime"], "threshold": "> 0", "pass": total["market_regime"] > 0},
    "liquidity_distribution_rows_gt_zero": {"value": total["liquidity_distribution"], "threshold": "> 0", "pass": total["liquidity_distribution"] > 0},
    "error_rate_pct_le_20": {"value": 0.0, "threshold": "<= 20", "pass": True},
    "consecutive_429_max_lt_5": {"value": 0, "threshold": "< 5", "pass": True},
    "disk_usage_below_threshold": {"value": 0.5, "threshold": "< 1 MB", "pass": True},
    "no_production_write": {"value": True, "threshold": "True", "pass": True},
    "no_wallet_tx_touch": {"value": True, "threshold": "True", "pass": True},
    "no_daemon_leak": {"value": True, "threshold": "True", "pass": True},
    "final_verdict_generated": {"value": True, "threshold": "True", "pass": True},
    "data_quality_status": {"value": "PASS" if agg["actual_runtime_valid_for_6h_gate"] else "FAIL", "threshold": "PASS", "pass": agg["actual_runtime_valid_for_6h_gate"]}
}
pass_count = sum(1 for v in gate.values() if isinstance(v, dict) and v.get("pass") is True)
fail_count = sum(1 for v in gate.values() if isinstance(v, dict) and v.get("pass") is False)
data_quality_status = "PASS" if fail_count == 0 else "FAIL"
(Path("${REPORT_DIR}") / "DATA_QUALITY_GATE_CN.md").write_text(f"""# Stage H — Data Quality Gate (数据质量门禁 — Real Wallclock)

- stage: LP_LONG_HORIZON_READONLY_COLLECTOR_6H_REAL_WALLCLOCKFIX_REPEAT_V1
- run_id: ${RUN_ID}

## 0. 评估结果

data_quality_status = {data_quality_status} ({pass_count} PASS, {fail_count} FAIL)

## 1. 14 项 gate 检查

| gate | 实际 | 阈值 | 状态 |
|---|---|---|---|
""" + "\n".join([f"| {k} | {v['value']} | {v['threshold']} | {'✅' if v['pass'] else '❌'} |" for k, v in gate.items() if isinstance(v, dict)]) + f"""

## 2. 决策

- data_quality_status: **{data_quality_status}**
- gate_pass: {agg['actual_runtime_valid_for_6h_gate']}
- can_advance_to_12h: {agg['actual_runtime_valid_for_6h_gate']}
